import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';            // ← import Link
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]       = useState([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState(null);

  const fetchEvents = async () => {
    try {
      setLoading(true);

      const token = localStorage.getItem('token');
      console.log("Token being sent:", token);

      const res   = await axios.get('http://localhost:5000/api/attendee/events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
    const id = setInterval(fetchEvents, 30000);
    return () => clearInterval(id);
  }, []);

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>
        <p>View your registered events, check your tickets, and join live sessions.</p>

        <section>
          <h3>Personalized Schedule</h3>
          {loading
            ? <p>Loading events…</p>
            : error
              ? <p style={{ color: 'red' }}>{error}</p>
              : events.length > 0
                ? (
                  <ul>
                    {events.map(evt => (
                      <li key={evt._id} style={{ marginBottom: '0.5rem' }}>
                        <strong>{evt.title}</strong> | {new Date(evt.date).toLocaleDateString()}<br/>
                        Ticket Type: {evt.ticketType || 'General'}<br/>
                        Session Link:{' '}
                        <Link
                          to={`/attendee/join?link=${encodeURIComponent(evt.sessionLink)}`}
                          style={{ color: '#bb86fc' }}
                        >
                          Join Session
                        </Link>
                      </li>
                    ))}
                  </ul>
                )
                : <p>No registered events found.</p>
          }
        </section>

        {/* other sections unchanged */}
      </div>
    </div>
  );
};

export default AttendeeDashboard;
